void permute(string str, string out, set<string> &ans)
{
    struct Frame {
        string str;
        string out;
        size_t idx;
    };
    std::stack<Frame> st;
    st.push({str, out, 0});
    while (!st.empty()) {
        Frame cur = st.top();
        st.pop();
        if (cur.str.empty()) {
            ans.insert(cur.out);
            continue;
        }
        if (cur.idx >= cur.str.size()) {
            continue;
        }
        string child_str = cur.str.substr(1);
        string child_out = cur.out + cur.str[0];
        rotate(cur.str.begin(), cur.str.begin() + 1, cur.str.end());
        ++cur.idx;
        st.push(std::move(cur));
        st.push({child_str, child_out, 0});
    }
}

