    std::stack<std::pair<int,bool>> st;
    st.push({n, false});
    std::string current;
    while (!st.empty()) {
        auto [cur, done] = st.top();
        st.pop();
        if (cur == 1) {
            current = "1";
            continue;
        }
        if (!done) {
            st.push({cur, true});
            st.push({cur - 1, false});
        } else {
            const std::string &say = current;
            std::string result;
            result.reserve(say.size() * 2);
