char kthCharacter(long long k, vector<int>& operations) {
    std::stack<int> opStack;
    long long curK = k;
    int n = operations.size();

    while (curK != 1) {
        long long len = 1;
        bool found = false;
        for (int i = 0; i < n; ++i) {
            len *= 2;
            if (len >= curK) {
                opStack.push(operations[i]);
                curK = curK - len / 2;
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    char res = 'a';
    while (!opStack.empty()) {
        int opType = opStack.top();
        opStack.pop();
        if (opType == 1) {
            if (res == 'z')
                res = 'a';
            else
                res = res + 1;
        }
    }
    return res;
}

