void solve(int n, string &curr, int &count, int k, string &result) {
    if (!result.empty()) return;

    struct Frame {
        string s;
        char next;
    };

    std::stack<Frame> st;
    st.push({curr, 'a'});

    while (!st.empty() && result.empty()) {
        Frame &fr = st.top();

        if ((int)fr.s.size() == n) {
            ++count;
            if (count == k) {
                result = fr.s;
            }
            st.pop();
            continue;
        }

        if (fr.next > 'c') {
            st.pop();
            continue;
        }

        char ch = fr.next++;
        if (!fr.s.empty() && fr.s.back() == ch) {
            continue;
        }

        Frame child;
        child.s = fr.s;
        child.s.push_back(ch);
        child.next = 'a';
        st.push(std::move(child));
    }
}

