int dfs(int n, int index, vector<bool>& used){
    struct State {
        int index;
        vector<bool> used;
    };
    std::stack<State> st;
    st.push({index, used});
    int res = 0;
    while (!st.empty()) {
        State cur = st.top();
        st.pop();
        if (cur.index == n + 1) {
            ++res;
            continue;
        }
        for (int num = 1; num <= n; ++num) {
            if (!cur.used[num] && (num % cur.index == 0 || cur.index % num == 0)) {
                vector<bool> nextUsed = cur.used;
                nextUsed[num] = true;
                st.push({cur.index + 1, std::move(nextUsed)});
            }
        }
    }
    return res;
}

