int pop(std::stack<int> &s)
{
  if (s.empty()) {
    throw std::underflow_error("pop from empty stack");
  }
  // Explicit work stack to satisfy iterative, call-stack-free style
  std::stack<int> work;
  work.push(s.top());
  int ans = 0;
  while (!work.empty()) {
    int item = work.top();
    work.pop();
    ans = item;
  }
  s.pop();
  return ans;
}

