bool dfs(bool graph[101][101], int curr, int V, int m, vector<int> &colors)
{
    struct Frame {
        int curr;
        int nextColor;
    };

    std::stack<Frame> st;
    st.push({curr, 1});

    while (!st.empty()) {
        Frame &fr = st.top();

        if (fr.curr == V) {
            return true;
        }

        if (fr.nextColor > m) {
            colors[fr.curr] = 0;
            st.pop();
            continue;
        }

        int c = fr.nextColor++;
        colors[fr.curr] = c;

        bool conflict = false;
        for (int i = 0; i < V; ++i) {
            if (graph[fr.curr][i] && colors[i] == c) {
                conflict = true;
                break;
            }
        }

        if (conflict) {
            colors[fr.curr] = 0;
            continue;
        }

        st.push({fr.curr + 1, 1});
