int binary_search(int arr[], int start, int end, int y, int &count)
{
    std::stack<std::pair<int,int>> st;
    st.push({start, end});
    while (!st.empty()) {
        int curStart = st.top().first;
        int curEnd   = st.top().second;
        st.pop();
        if (curStart >= curEnd) {
            return curStart;
        }
        int mid = (curStart + curEnd) / 2;
        ++count;
        if (arr[mid] > y) {
            st.push({curStart, mid});
        } else {
            st.push({mid + 1, curEnd});
        }
    }
    return start;
}

