using namespace std;

int minimumSteps(int a, int b, int c) {
    struct State { int a; int b; int c; };
    std::stack<State> st;
    st.push({a, b, c});

    while (!st.empty()) {
        State cur = st.top();
        st.pop();
        int ca = cur.a;
        int cb = cur.b;
        int cc = cur.c;

        if (ca < 1 || cb < 1) {
            return -1;
        }
        if (ca == 1 && cb == 1) {
            return cc;
        }
        if (ca < cb) {
            int tmp = ca + cb;
            cb = tmp - cb;
            ca = tmp - cb;
        }
        st.push({ca - cb, cb, cc + 1});
    }
    return -1;
}

