int minPalPartion(string String,int i,int j) {
    if(i>=j || isPalindrome(String,i,j)) return 0;
    unordered_map<long long,int> memo;
    auto keyOf = [](int a,int b)->long long{ return ( (static_cast<long long>(a) << 32) | (unsigned int)b ); };
    stack<pair<int,int>> st;
    st.push({i,j});
    while(!st.empty()){
        auto [curI,curJ] = st.top(); st.pop();
        long long kkey = keyOf(curI,curJ);
        if(memo.find(kkey)!=memo.end()) continue;
        if(curI>=curJ || isPalindrome(String,curI,curJ)){
            memo[kkey]=0;
            continue;
        }
        bool ready = true;
        int best = INT_MAX;
        for(int k=curI;k<curJ;k++){
            long long leftKey = keyOf(curI,k);
            long long rightKey = keyOf(k+1,curJ);
            if(memo.find(leftKey)==memo.end() || memo.find(rightKey)==memo.end()){
                ready = false;
                st.push({curI,k});
                st.push({k+1,curJ});
            }else{
                int cand = memo[leftKey] + memo[rightKey] + 1;
                if(cand < best) best = cand;
            }
        }
        if(!ready){
            st.push({curI,curJ});
            continue;
        }
        memo[kkey]=best;
    }
    return memo[keyOf(i,j)];
}

