void accumulate_arr(int arr[], int len) {
    if (len <= 1) return;

    struct Frame {
        int len;
        bool done;
    };

    std::stack<Frame> st;
    st.push({len, false});

    while (!st.empty()) {
        Frame f = st.top();
        st.pop();

        if (f.len <= 1) continue;

        if (!f.done) {
            // simulate the recursive call accumulate_arr(arr, len-1)
            st.push({f.len, true});          // work to do after child returns
            st.push({f.len - 1, false});     // child call
        } else {
            // post-recursion work: arr[len-1] += arr[len-2]
            arr[f.len - 1] += arr[f.len - 2];
