    if (n == 0) return 1.0;

    struct Frame {
        double x;
        int n;
        int stage;   // 0 = entry, 1 = after child returned
        double t;    // value returned by child
    };

    std::stack<Frame> st;
    st.push({x, n, 0, 0.0});

    double finalResult = 1.0;
    while (!st.empty()) {
        Frame &fr = st.top();

        if (fr.n == 0) {
            fr.t = 1.0;
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                parent.t = fr.t;
                parent.stage = 1;
            }
            continue;
        }

        if (fr.stage == 0) {
            fr.stage = 1;
            int next_n = fr.n / 2;
            st.push({fr.x, next_n, 0, 0.0});
            continue;
        } else {
            double t = fr.t;
            double res;
            if (fr.n % 2 == 0) {
                res = t * t;
            } else if (fr.n > 0) {
                res = t * t * fr.x;
            } else {
                res = t * t / fr.x;
            }
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                parent.t = res;
                parent.stage = 1;
            } else {
                finalResult = res;
            }
        }
    }
    return finalResult;
}

