int solve(vector<string> vec, int A, int B, int idx) {
    struct State { int idx; int A; int B; int len; };
    stack<State> st;
    st.push({idx, A, B, 0});
    int best = 0;
    while (!st.empty()) {
        State cur = st.top(); st.pop();
        if (cur.idx == (int)vec.size()) {
            if (cur.len > best) best = cur.len;
            continue;
        }
        // exclude current string
        st.push({cur.idx + 1, cur.A, cur.B, cur.len});
        int zero = count0(vec[cur.idx]);
        int one = (int)vec[cur.idx].size() - zero;
        if (zero <= cur.A && one <= cur.B) {
            // include current string
            st.push({cur.idx + 1, cur.A - zero, cur.B - one, cur.len + 1});
        }
    }
    return best;
}
int MaxSubsetlength(vector<string> arr, int A, int B) {
