#include <vector>
#include <stack>
#include <algorithm>

std::string sort(std::string s) {
    if (s.empty()) return s;

    std::vector<char> c(s.begin(), s.end());

    // iterative quicksort using an explicit stack instead of recursion
    std::stack<std::pair<std::size_t, std::size_t>> st;
    st.push({0, c.size() - 1});
    while (!st.empty()) {
        auto [lo, hi] = st.top();
        st.pop();
        if (lo >= hi) continue;

        char pivot = c[lo + (hi - lo) / 2];
        std::size_t i = lo;
        std::size_t j = hi;
        while (i <= j) {
            while (c[i] < pivot) ++i;
            while (c[j] > pivot) {
                if (j == 0) break;
                --j;
            }
            if (i <= j) {
                std::swap(c[i], c[j]);
                ++i;
                if (j == 0) break;
                --j;
            }
        }
        if (lo < j) st.push({lo, j});
        if (i < hi) st.push({i, hi});
    }

    std::size_t al_c = 0;
    std::size_t nu_c = 0;
    while (al_c < c.size() && c[al_c] < 'a') ++al_c;

