using namespace std;
void deleteMid(stack<char >&st,int n,int curr=0) {
    if(st.empty() || curr==n || n<=0) return;
    struct Frame {
        int curr;
        char x;
        bool done;
    };
    stack<Frame> sim;
    sim.push({curr, 0, false});
    while(!sim.empty()) {
        Frame &f = sim.top();
        if(st.empty() || f.curr == n) {
            sim.pop();
            continue;
        }
        if(!f.done) {
            f.done = true;
            f.x = st.top();
            st.pop();
            sim.push({f.curr + 1, 0, false});
        } else {
            if(f.curr != n/2) {
                st.push(f.x);
            }
            sim.pop();
        }
    }
}

