#include <stack>
#include <utility>

int gcd(int a, int b){
    std::stack<std::pair<int,int>> st;
    st.push({a, b});
    while(!st.empty()){
        auto [a_cur, b_cur] = st.top();
        st.pop();
        if(a_cur > b_cur) std::swap(a_cur, b_cur);
        if(a_cur == 0) return b_cur;
        st.push({b_cur % a_cur, a_cur});
    }
    return 0;
}

