bool isWinning(int pos) {
  if (pos <= 0) return false;
  const int moves[3] = {1, 3, 4};

  std::stack<int> st;
  std::stack<int> order;
  std::unordered_set<int> seen;

  st.push(pos);
  while (!st.empty()) {
    int cur = st.top(); st.pop();
    if (seen.contains(cur)) continue;
    seen.insert(cur);
    order.push(cur);
    for (int m : moves) {
      int nxt = cur - m;
      if (nxt >= 0) st.push(nxt);
    }
  }

  std::unordered_map<int,bool> memo;
  memo[0] = false;

  while (!order.empty()) {
    int cur = order.top(); order.pop();
    if (memo.contains(cur)) continue;
    bool win = false;
    for (int m : moves) {
      int nxt = cur - m;
      if (nxt >= 0 && memo.contains(nxt) && !memo[nxt]) {
        win = true;
        break;
      }
    }
    memo[cur] = win;
  }
  return memo[pos];
}

