void get_next(int m, int state, int index, int next_state, vector<int>& next) {
    struct Item {
        int state;
        int index;
        int next_state;
    };

    std::stack<Item> st;
    st.push({state, index, next_state});

    while (!st.empty()) {
        Item cur = st.top();
        st.pop();

        if (cur.index == m) {
            next.push_back(cur.next_state);
            continue;
        }

        // push children in reverse order so that color 0,1,2 are processed
        // in the same order as the original recursion
        for (int color = 2; color >= 0; --color) {
            if (color == cur.state % 3) continue;
            if (cur.index > 0 && color == cur.next_state % 3) continue;
            Item nxt{cur.state / 3, cur.index + 1, cur.next_state * 3 + color};
            st.push(nxt);
        }
    }
}

