double Sqrt(double a) {
    std::stack<double> st;
    st.push(a);
    bool invert = false;
    const double epsilon = 1e-12;

    while (!st.empty()) {
        double cur = st.top();
        st.pop();

        if (cur > 0 && cur < 1) {
            invert = true;
            st.push(1.0 / cur);
            continue;
        }

        double l = 0, r = cur;
        double res = -1;
        while (l <= r) {
            double mid = (l + r) / 2;
            if (mid * mid > cur) {
                r = mid;
            } else {
                if (cur - mid * mid < epsilon) {
                    res = mid;
                    break;
                }
                l = mid;
            }
        }
        if (invert && res > 0) {
            res = 1.0 / res;
        }
        return res;
    }
    return -1;
}

