#include <stdlib.h>
#include <stack>
using namespace std;

void printBinStr(int*str,int len) {
    for(int i=0;i<len;i++) {
        cout<<str[i];
    }
    cout<<endl;
}

void generateBinStr(int*str,int len,int currlen,int occur,int nextbit) {
    struct Frame {
        int currlen;
        int occur;
        int nextbit;
    };
    std::stack<Frame> st;
    st.push({currlen, occur, nextbit});
    while(!st.empty()) {
        Frame cur = st.top();
        st.pop();
        int c_len = cur.currlen;
        int c_occur = cur.occur;
        int c_next = cur.nextbit;

        if(c_len == len) {
            if(c_occur == 2 && c_next == 0) printBinStr(str, len);
            continue;
        }
        if(c_len == 0) {
            str[0] = c_next;
            st.push({c_len + 1, c_occur, 1});
            st.push({c_len + 1, c_occur, 0});
        } else {
            if(c_occur < 2) {
                str[c_len] = c_next;
                int new_occur = c_occur + (str[c_len - 1] == 0 && c_next == 1 ? 1 : 0);
                st.push({c_len + 1, new_occur, 1});
                st.push({c_len + 1, new_occur, 0});
            } else {
                if(str[c_len - 1] == 0 && c_next == 1) {
                    continue;
                } else {
                    str[c_len] = c_next;
                    st.push({c_len + 1, c_occur, 1});
                    st.push({c_len + 1, c_occur, 0});
                }
            }
        }
    }
}

