bool dfs(string& s, int index, int& cnt, int n, int k){
    struct Frame {
        int idx;
        int next; // next char to try in "abc"
    };
    std::stack<Frame> st;
    st.push({index, 0});
    const char chars[3] = {'a','b','c'};
    while(!st.empty()){
        Frame &fr = st.top();
        int idx = fr.idx;
        if(idx == n){
            ++cnt;
            st.pop();
            if(cnt == k) return true;
            continue;
        }
        if(fr.next >= 3){
            st.pop();
            continue;
        }
        char c = chars[fr.next];
        ++fr.next;
        if(!idx || c != s[idx - 1]){
            s[idx] = c;
            st.push({idx + 1, 0});
        }
    }
    return false;
}

