using namespace std;
int countGroups(int position,int previous_sum,int length,char*num) {
    struct Frame {
        int position;
        int previous_sum;
        int length;
        char* num;
        int next_index;
        int current_sum;
        int res;
    };
    std::stack<Frame> st;
    st.push({position, previous_sum, length, num, position, 0, 0});
    while(!st.empty()){
        Frame &f = st.top();
        if(f.position == f.length){
            int ret = 1;
            st.pop();
            if(st.empty()) return ret;
            st.top().res += ret;
            continue;
        }
        if(f.next_index >= f.length){
            int ret = f.res;
            st.pop();
            if(st.empty()) return ret;
            st.top().res += ret;
            continue;
        }
        f.current_sum += f.num[f.next_index] - '0';
        if(f.current_sum >= f.previous_sum){
            int child_pos = f.next_index + 1;
            int child_prev = f.current_sum;
            f.next_index++;
            st.push({child_pos, child_prev, f.length, f.num, child_pos, 0, 0});
        }else{
            f.next_index++;
        }
    }
    return 0;
}

