using namespace std;
#include <stack>

int countDigit(long long n) {
    std::stack<long long> st;
    st.push(n);
    int cnt = 0;
    while (!st.empty()) {
        long long cur = st.top();
        st.pop();
        ++cnt;                       // the recursive call would contribute 1
        long long next = cur / 10;   // the argument the recursive call would receive
        if (next != 0) {             // base case in original: n/10 == 0 -> stop
            st.push(next);
        }
    }
    return cnt;
}
